CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS zones(id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, coastline TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS response_plans(id TEXT PRIMARY KEY, zone_id TEXT NOT NULL REFERENCES zones(id), name TEXT NOT NULL, level INTEGER NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, starts_at TEXT NOT NULL, ends_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS shelters(id TEXT PRIMARY KEY, zone_id TEXT NOT NULL REFERENCES zones(id), name TEXT NOT NULL, capacity INTEGER NOT NULL, occupied INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS shelter_assignments(id TEXT PRIMARY KEY, shelter_id TEXT NOT NULL REFERENCES shelters(id), household_ref TEXT NOT NULL, people INTEGER NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, released_at TEXT, UNIQUE(shelter_id, household_ref));
CREATE TABLE IF NOT EXISTS supplies(id TEXT PRIMARY KEY, zone_id TEXT NOT NULL REFERENCES zones(id), sku TEXT NOT NULL, name TEXT NOT NULL, unit TEXT NOT NULL, reorder_point INTEGER NOT NULL, created_at TEXT NOT NULL, UNIQUE(zone_id, sku));
CREATE TABLE IF NOT EXISTS supply_lots(id TEXT PRIMARY KEY, supply_id TEXT NOT NULL REFERENCES supplies(id), lot_code TEXT NOT NULL, quantity INTEGER NOT NULL, reserved INTEGER NOT NULL DEFAULT 0, expires_at TEXT, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(supply_id, lot_code));
CREATE TABLE IF NOT EXISTS relief_requests(id TEXT PRIMARY KEY, zone_id TEXT NOT NULL REFERENCES zones(id), requester_id TEXT NOT NULL REFERENCES users(id), idempotency_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL, priority INTEGER NOT NULL, destination TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, submitted_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS request_items(id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES relief_requests(id), supply_id TEXT NOT NULL REFERENCES supplies(id), quantity INTEGER NOT NULL, allocated INTEGER NOT NULL DEFAULT 0, UNIQUE(request_id, supply_id));
CREATE TABLE IF NOT EXISTS allocations(id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES relief_requests(id), lot_id TEXT NOT NULL REFERENCES supply_lots(id), quantity INTEGER NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(request_id, lot_id));
CREATE TABLE IF NOT EXISTS dispatches(id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES relief_requests(id), driver TEXT NOT NULL, vehicle TEXT NOT NULL, status TEXT NOT NULL, attempt INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL, delivered_at TEXT, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS incidents(id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES response_plans(id), reporter_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, severity INTEGER NOT NULL, status TEXT NOT NULL, context_note TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS incident_actions(id TEXT PRIMARY KEY, incident_id TEXT NOT NULL REFERENCES incidents(id), actor_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, note TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events(id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), object_type TEXT NOT NULL, object_id TEXT NOT NULL, action TEXT NOT NULL, result TEXT NOT NULL, request_id TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency_keys(key TEXT PRIMARY KEY, request_hash TEXT NOT NULL, response_body TEXT NOT NULL, status_code INTEGER NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS worker_jobs(id TEXT PRIMARY KEY, kind TEXT NOT NULL, entity_id TEXT NOT NULL, state TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, run_after TEXT NOT NULL, last_error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(kind, entity_id));
CREATE INDEX IF NOT EXISTS idx_requests_zone_status ON relief_requests(zone_id, status, priority);
CREATE INDEX IF NOT EXISTS idx_lots_supply_status ON supply_lots(supply_id, status, expires_at);
CREATE INDEX IF NOT EXISTS idx_audit_object ON audit_events(object_type, object_id, created_at);
CREATE INDEX IF NOT EXISTS idx_jobs_due ON worker_jobs(state, run_after);
